import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Sandboxing","description":"","frontmatter":{"title":"Sandboxing"},"headers":[],"relativePath":"docs/privacy-and-security/sandboxing.md","filePath":"docs/privacy-and-security/sandboxing.md","lastUpdated":1790284433000}'),s={name:"docs/privacy-and-security/sandboxing.md"};function r(i,e,d,l,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="sandboxing" tabindex="-1">Sandboxing <a class="header-anchor" href="#sandboxing" aria-label="Permalink to &quot;Sandboxing&quot;">​</a></h1><p>OrbySystems never gives an LLM, or code an LLM writes or hands off to, the run of your machine. Anything that executes Python or other arbitrary code runs inside a sandbox — limited to exactly what it needs to see on disk and reach over the network to do its job.</p><h2 id="the-general-sandbox" tabindex="-1">The general sandbox <a class="header-anchor" href="#the-general-sandbox" aria-label="Permalink to &quot;The general sandbox&quot;">​</a></h2><p>The model&#39;s Python tool — used when it writes and runs a script, e.g. for analysis — runs inside a sandbox that:</p><ul><li>can read and write only its own dedicated workspace, never your personal files or the rest of your home directory</li><li>has no network access by default; only hosts you explicitly add to the allowlist in <a href="/docs/settings/sandbox">Settings → Sandbox</a> are reachable, for cases like installing a Python library a generated script depends on</li></ul><h2 id="the-isolated-parser-sandbox" tabindex="-1">The isolated parser sandbox <a class="header-anchor" href="#the-isolated-parser-sandbox" aria-label="Permalink to &quot;The isolated parser sandbox&quot;">​</a></h2><p>Bank statement and CSV parsers — both the ones bundled with OrbySystems and any you&#39;ve dropped in yourself — run in a second, separate sandbox dedicated just to parsing, whether that&#39;s a real import, previewing a parser you&#39;re building, or running its tests. This sandbox denies network access entirely, with no allowlist at all: a parser&#39;s only job is turning a document already on your disk into structured data, so it never has a legitimate reason to reach the network — meaning even a malicious or buggy parser can&#39;t exfiltrate anything from the statement it&#39;s reading.</p>',7)])])}const p=a(s,[["render",r]]);export{u as __pageData,p as default};
